std::vector<Polygon2d> faces;
for (Arrangement2::Face_const_iterator fit = arr.faces_begin(); fit != arr.faces_end(); ++fit) {
    if (!fit->is_unbounded()) {
        std::vector<Point2d> polygon;
        Arrangement2::Ccb_halfedge_const_circulator circ = fit->outer_ccb();
        Arrangement2::Ccb_halfedge_const_circulator begin = circ;
        do {
            Point_2 cgal_point = circ->source()->point();
            polygon.push_back(Point2d(cgal_point.x(), cgal_point.y()));
            ++circ;
        } while (circ != begin);
        faces.push_back(polygon);
    }
}
return faces;

